import{_ as t,a0 as c,w as s,s as a,ao as r,I as i,x as o,a1 as p,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"有用的 Bash 快捷键清单 | LCTT x X-CMD","titleTemplate":false,"description":"有用的 Bash 快捷键清单 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有用的 Bash 快捷键清单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有用的 Bash 快捷键清单 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180217 The List Of Useful Bash Keyboard Shortcuts","title":"有用的 Bash 快捷键清单","tag":"201803","desc":""},"relativePath":"201803/20180217 The List Of Useful Bash Keyboard Shortcuts.md","filePath":"[post].md"}'),T={name:"201803/20180217 The List Of Useful Bash Keyboard Shortcuts.md"};function n(L,e,C,h,R,u){const d=c("Link");return s(),a("div",null,[e[13]||(e[13]=r('<h1 id="有用的-bash-快捷键清单" tabindex="-1">有用的 Bash 快捷键清单 <a class="header-anchor" href="#有用的-bash-快捷键清单" aria-label="Permalink to “有用的 Bash 快捷键清单”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/02/Bash-720x340.jpg" alt=""></p><p>现如今，我在终端上花的时间更多，尝试在命令行完成比在图形界面更多的工作。随着时间推移，我学了许多 BASH 的技巧。这是一份每个 Linux 用户都应该知道的 BASH 快捷键，这样在终端做事就会快很多。我不会说这是一份完全的 BASH 快捷键清单，但是这足够让你的 BASH shell 操作比以前更快了。学习更快地使用 BASH 不仅节省了更多时间，也让你因为学到了有用的知识而感到自豪。那么，让我们开始吧。</p><h3 id="alt-快捷键" tabindex="-1">ALT 快捷键 <a class="header-anchor" href="#alt-快捷键" aria-label="Permalink to “ALT 快捷键”">​</a></h3><ol><li><p><code>ALT+A</code> – 光标移动到行首。</p></li><li><p><code>ALT+B</code> – 光标移动到所在单词词首。</p></li><li><p><code>ALT+C</code> – 终止正在运行的命令/进程。与 <code>CTRL+C</code> 相同。</p></li><li><p><code>ALT+D</code> – 关闭空的终端（也就是它会关闭没有输入的终端）。也删除光标后的全部字符。</p></li><li><p><code>ALT+F</code> – 移动到光标所在单词词末。</p></li><li><p><code>ALT+T</code> – 交换最后两个单词。</p></li><li><p><code>ALT+U</code> – 将单词内光标后的字母转为大写。</p></li><li><p><code>ALT+L</code> – 将单词内光标后的字母转为小写。</p></li><li><p><code>ALT+R</code> – 撤销对从历史记录中带来的命令的修改。</p><p>正如你在上面输出所见，我使用反向搜索拉取了一个指令，并更改了那个指令的最后一个字母，并使用 <code>ALT+R</code> 撤销了更改。</p></li><li><p><code>ALT+.</code> （注意末尾的点号） – 使用上一条命令的最后一个单词。</p></li></ol><p>如果你想要对多个命令进行相同的操作的话，你可以使用这个快捷键来获取前几个指令的最后一个单词。例如，我需要使用 <code>ls -r</code> 命令输出以文件名逆序排列的目录内容。同时，我也想使用 <code>uname -r</code> 命令来查看我的内核版本。在这两个命令中，相同的单词是 <code>-r</code> 。这就是需要 <code>ALT+.</code> 的地方。快捷键很顺手。首先运行 <code>ls -r</code> 来按文件名逆序输出，然后在其他命令，比如 <code>uname</code> 中使用最后一个单词 <code>-r</code> 。</p><h3 id="ctrl-快捷键" tabindex="-1">CTRL 快捷键 <a class="header-anchor" href="#ctrl-快捷键" aria-label="Permalink to “CTRL 快捷键”">​</a></h3><ol><li><p><code>CTRL+A</code> – 快速移动到行首。</p><p>我们假设你输入了像下面这样的命令。当你在第 N 行时，你发现在行首字符有一个输入错误</p></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gind . -mtime -1 -type</span></span></code></pre></div><pre><code>注意到了吗？上面的命令中我输入了 `gind` 而不是 `find` 。你可以通过一直按着左箭头键定位到第一个字母然后用 `g` 替换 `f` 。或者，仅通过  `CTRL+A` 或 `HOME` 键来立刻定位到行首，并替换拼错的单词。这将节省你几秒钟的时间。\n</code></pre><ol start="2"><li><p><code>CTRL+B</code> – 光标向前移动一个字符。</p><p>这个快捷键可以使光标向前移动一个字符，即光标前的一个字符。或者，你可以使用左箭头键来向前移动一个字符。</p></li><li><p><code>CTRL+C</code> – 停止当前运行的命令。</p><p>如果一个命令运行时间过久，或者你误运行了，你可以通过使用 <code>CTRL+C</code> 来强制停止或退出。</p></li><li><p><code>CTRL+D</code> – 删除光标后的一个字符。</p><p>如果你的系统退格键无法工作的话，你可以使用 <code>CTRL+D</code> 来删除光标后的一个字符。这个快捷键也可以让你退出当前会话，和 exit 类似。</p></li><li><p><code>CTRL+E</code> – 移动到行末。</p><p>当你修正了行首拼写错误的单词，按下 <code>CTRL+E</code> 来快速移动到行末。或者，你也可以使用你键盘上的 <code>END</code> 键。</p></li><li><p><code>CTRL+F</code> – 光标向后移动一个字符。</p><p>如果你想将光标向后移动一个字符的话，按 <code>CTRL+F</code> 来替代右箭头键。</p></li><li><p><code>CTRL+G</code> – 退出历史搜索模式，不运行命令。</p><p>正如你在上面的截图看到的，我进行了反向搜索，但是我执行命令，并退出了历史搜索模式。</p></li><li><p><code>CTRL+H</code> – 删除光标签的一个字符，和退格键相同。</p></li><li><p><code>CTRL+J</code> – 和 ENTER/RETURN 键相同。</p><p>回车键不工作？没问题！ <code>CTRL+J</code> 或 <code>CTRL+M</code> 可以用来替换回车键。</p></li><li><p><code>CTRL+K</code> – 删除光标后的所有字符。</p><p>你不必一直按着删除键来删除光标后的字符。只要按 <code>CTRL+K</code> 就能删除光标后的所有字符。</p></li><li><p><code>CTRL+L</code> – 清空屏幕并重新显示当前行。</p><p>别输入 <code>clear</code> 来清空屏幕了。只需按 <code>CTRL+M</code> 即可清空并重新显示当前行。</p></li><li><p><code>CTRL+M</code> – 和 <code>CTRL+J</code> 或 RETURN键相同。</p></li><li><p><code>CTRL+N</code> – 在命令历史中显示下一行。</p><p>你也可以使用下箭头键。</p></li><li><p><code>CTRL+O</code> – 运行你使用反向搜索时发现的命令，即 CTRL+R。</p></li><li><p><code>CTRL+P</code> – 显示命令历史的上一条命令。</p><p>你也可以使用上箭头键。</p></li><li><p><code>CTRL+R</code> – 向后搜索历史记录（反向搜索）。</p></li><li><p><code>CTRL+S</code> – 向前搜索历史记录。</p></li><li><p><code>CTRL+T</code> – 交换最后两个字符。</p><p>这是我最喜欢的一个快捷键。假设你输入了 <code>sl</code> 而不是 <code>ls</code> 。没问题！这个快捷键会像下面这张截图一样交换字符。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/CTRLT-1.gif" alt=""></p></li><li><p><code>CTRL+U</code> – 删除光标前的所有字符（从光标后的点删除到行首）。</p><p>这个快捷键立刻删除前面的所有字符。</p></li><li><p><code>CTRL+V</code> – 逐字显示输入的下一个字符。</p></li><li><p><code>CTRL+W</code> – 删除光标前的一个单词。</p><p>不要和 CTRL+U 弄混了。CTRL+W 不会删除光标前的所有东西，而是只删除一个单词。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/CTRLW-1.gif" alt=""></p></li><li><p><code>CTRL+X</code> – 列出当前单词可能的文件名补全。</p></li><li><p><code>CTRL+XX</code> – 移动到行首位置（再移动回来）。</p></li><li><p><code>CTRL+Y</code> – 恢复你上一个删除或剪切的条目。</p><p>记得吗，我们在第 21 个命令用 <code>CTRL+W</code> 删除了单词“-al”。你可以使用 <code>CTRL+Y</code> 立刻恢复。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/CTRLY-1.gif" alt=""></p><p>看见了吧？我没有输入“-al”。取而代之，我按了 <code>CTRL+Y</code> 来恢复它。</p></li><li><p><code>CTRL+Z</code> – 停止当前的命令。</p><p>你也许很了解这个快捷键。它终止了当前运行的命令。你可以在前台使用 <code>fg</code> 或在后台使用 <code>bg</code> 来恢复它。</p></li><li><p><code>CTRL+[</code> – 和 <code>ESC</code> 键等同。</p></li></ol><h3 id="杂项" tabindex="-1">杂项 <a class="header-anchor" href="#杂项" aria-label="Permalink to “杂项”">​</a></h3><ol><li><p><code>!!</code> – 重复上一个命令。</p></li><li><p><code>ESC+t</code> – 交换最后两个单词。</p></li></ol><p>这就是我所能想到的了。将来我遇到 Bash 快捷键时我会持续添加的。如果你觉得文章有错的话，请在下方的评论区留言。我会尽快更新。</p><p>Cheers!</p><hr>',16)),i("p",null,[e[1]||(e[1]=o("via: ",-1)),p(d,{href:"https://www.ostechnix.com/list-useful-bash-keyboard-shortcuts/"},{default:l(()=>[...e[0]||(e[0]=[o("https://www.ostechnix.com/list-useful-bash-keyboard-shortcuts/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=o("作者：",-1)),p(d,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...e[2]||(e[2]=[o("SK",-1)])]),_:1}),e[6]||(e[6]=o(" 译者：",-1)),p(d,{href:"https://github.com/heart4lor"},{default:l(()=>[...e[3]||(e[3]=[o("heart4lor",-1)])]),_:1}),e[7]||(e[7]=o(" 校对：",-1)),p(d,{href:"https://github.com/wxy"},{default:l(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=o("本文由 ",-1)),p(d,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原创编译，",-1)),p(d,{href:"https://linux.cn/"},{default:l(()=>[...e[9]||(e[9]=[o("Linux中国",-1)])]),_:1}),e[12]||(e[12]=o(" 荣誉推出",-1))])])}const b=t(T,[["render",n]]);export{g as __pageData,b as default};
